python3 - <<'PY'
import json

# Check the JSON structure to find the monthly data
with open('/app/resources/treasury_bulletin_2021_12.json', 'r') as f:
    data = json.load(f)

# Print top-level keys
print("Top-level keys:", list(data.keys())[:10])

# Look for tables with receipt data
def find_key(obj, target):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if target.lower() in k.lower():
                print(f"Found: {k}")
            find_key(v, target)
    elif isinstance(obj, list) and len(obj) > 0:
        find_key(obj[0], target)

# Just check what pages exist
if 'pages' in data:
    print(f"Number of pages: {len(data['pages'])}")
    for i, page in enumerate(data['pages'][:3]):
        print(f"Page {i}: {page.get('name', 'unnamed')[:100]}")
elif 'sections' in data:
    print("Has sections")
PY

